#!/usr/bin/env node
// Embeds the Windows scripts into the worker (p5-sandbox-ops, p9-windows-host-isolation): the worker and its
// privileged helper materialise and verify them from their own signed bundle, so no extra file has to reach the
// machine.
//   infra/worker/windows/remyral-jobrun.ps1     → apps/worker/src/sandbox/host/windows-jobrun.generated.ts
//   infra/worker/windows/remyral-job-slots.ps1  → apps/worker/src/sandbox/host/windows-job-slots.generated.ts
//   node scripts/release/gen-windows-jobrun.mjs          write the generated files
//   node scripts/release/gen-windows-jobrun.mjs --check  exit 1 when a generated file is stale
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const repo = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

export const SCRIPTS = [
  {
    source: 'infra/worker/windows/remyral-jobrun.ps1',
    generated: join(repo, 'apps/worker/src/sandbox/host/windows-jobrun.generated.ts'),
    name: 'WINDOWS_JOBRUN',
  },
  {
    source: 'infra/worker/windows/remyral-job-slots.ps1',
    generated: join(repo, 'apps/worker/src/sandbox/host/windows-job-slots.generated.ts'),
    name: 'WINDOWS_JOB_SLOTS',
  },
];

/** Kept for the job runner's existing test and callers. */
export const GENERATED = SCRIPTS[0].generated;

export function generateScript(entry) {
  const text = readFileSync(join(repo, entry.source), 'utf8').replace(/\r\n/g, '\n');
  const sha = createHash('sha256').update(text, 'utf8').digest('hex');
  return [
    `// Generated by scripts/release/gen-windows-jobrun.mjs from ${entry.source} - do not edit.`,
    `export const ${entry.name}_SHA256 = '${sha}';`,
    `export const ${entry.name}_PS1 = ${JSON.stringify(text)};`,
    '',
  ].join('\n');
}

export function generate() {
  return generateScript(SCRIPTS[0]);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  let stale = false;
  for (const entry of SCRIPTS) {
    const want = generateScript(entry);
    if (process.argv.includes('--check')) {
      let have = '';
      try {
        have = readFileSync(entry.generated, 'utf8');
      } catch {
        /* missing */
      }
      if (have !== want) {
        console.error(`${entry.generated} is stale: run node scripts/release/gen-windows-jobrun.mjs`);
        stale = true;
      }
    } else {
      writeFileSync(entry.generated, want);
    }
  }
  if (stale) process.exit(1);
}
